package com.bct.ngtpa.apiservice.application.dto.session.authenticated;import java.time.*;import java.util.Objects;public record TouchAuthenticatedSessionCommand(AuthenticatedSessionId authenticatedSessionId,ProtectedAuthenticatedSession protectedSession,Duration ttl,Instant touchedAt,String correlationId){public TouchAuthenticatedSessionCommand{Objects.requireNonNull(authenticatedSessionId);Objects.requireNonNull(protectedSession);Objects.requireNonNull(ttl);Objects.requireNonNull(touchedAt);if(ttl.isZero()||ttl.isNegative())throw new IllegalArgumentException("ttl must be positive");correlationId=optional(correlationId);}private static String optional(String v){return v==null||v.isBlank()?null:v.trim();}@Override public String toString(){return "TouchAuthenticatedSessionCommand[id=<redacted>, protectedSession=<redacted>, ttl="+ttl+", touchedAt="+touchedAt+", correlationId="+correlationId+"]";}}
